import { Link } from 'react-router-dom'
import usePageMetadata from '../../hooks/usePageMetadata'
import Breadcrumb from '../../components/shared/Breadcrumb'
import { NOTEBOOK } from '../../content/learnResources'
import notebookHtml from '../../content/learn/first-10-minutes.html?raw'
import layout from '../../components/method/MethodPage.module.css'
import styles from './FirstTenMinutes.module.css'

/*
 * Your first 10 minutes with BioTSR, as a recorded run: the notebook exactly
 * as it ran, outputs included, to read in the site.
 *
 * The body is generated by scripts/learn/notebook_preview.py from the
 * executed notebook in public/learn-files/ (the same file visitors
 * download), so every output shown is that run's. It is static HTML from
 * nbconvert with no scripts, rendered as it is; this page adds the title,
 * the notice that nothing here runs, and the download.
 */

const runDate = new Intl.DateTimeFormat('en-GB', {
  day: 'numeric',
  month: 'long',
  year: 'numeric',
  timeZone: 'UTC',
}).format(new Date(`${NOTEBOOK.recordedOn}T00:00:00Z`))

export default function FirstTenMinutes() {
  usePageMetadata({
    title: 'Your first 10 minutes with BioTSR (recorded run)',
    description:
      'A Jupyter notebook run with BioTSR 1.0.0: compute every triangle of ubiquitin, find the four triangles that share key 17637781, and count the keys ubiquitin, barnase and barstar share. Read the recorded run or download the notebook.',
  })

  return (
    <article className={layout.page}>
      <header className={styles.header}>
        <Breadcrumb
          trail={[
            { to: '/software', label: 'BioTSR' },
            { to: '/software/learn', label: 'Learn BioTSR' },
          ]}
          current="Your first 10 minutes (recorded run)"
        />
        <h1 className={layout.title}>Your first 10 minutes with BioTSR</h1>
        <div className={styles.notice} role="note">
          <p>
            <strong>A recorded run.</strong> This page shows the notebook exactly as it ran on{' '}
            {runDate} with BioTSR 1.0.0, from a clean environment, with every output it produced.
            It is a page to read: nothing here runs in your browser.
          </p>
          <p>
            <a className={styles.download} href={NOTEBOOK.href} download={NOTEBOOK.downloadName}>
              Download the notebook (.ipynb)
            </a>{' '}
            to run it yourself, or go back to <Link to="/software/learn#run">Learn BioTSR</Link> for
            how to open it.
          </p>
        </div>
      </header>

      <div className={styles.notebook} dangerouslySetInnerHTML={{ __html: notebookHtml }} />
    </article>
  )
}
